function CatHouseMgr:__delete()
    self.isMyself = nil
    self.preShowCatsId = nil
    if self.handler then
        Events.RemoveListener(Constants.EventNames.CatHouseDynamicCatChangeEventName, self.handler)
    end
    self.handler = nil
    -- 注销qi
    if self.handlerSwitch then
        Events.RemoveListener(Constants.EventNames.CatHouseSwitchUserEvent, self.handlerSwitch)
    end
    self.handlerSwitch = nil
    if self.handlerGet then
        Events.RemoveListener(CAT_GET_POPUP_FINISH, self.handlerGet)
    end
    self.handlerGet = nil
    if not isNull(self.cat_coroutine) then
        cs_coroutine.stop(self.cat_coroutine)
        self.cat_coroutine = nil
    end
    if self.sceneCos and next(self.sceneCos) then
        for i, co in ipairs(self.sceneCos) do
            if not isNull(co) then
                cs_coroutine.stop(co)
            end
        end
    end
    local SceneManagementIns = SceneManagement:GetInstance()
    for i, v in ipairs(ScenesConfig) do
        SceneManagementIns:UnloadAppendedSceneById(v)
    end

    xTry(function()
        if CatHouseExploreMgr then
            CatHouseExploreMgr:Delete()
            CatHouseExploreMgr = nil
        end
    end)
    
    self:ClearPath2Texture(false, true)
    self:ClearPath2Texture(true, true)

    self:CleanTimerGeneRateUp()

    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld(Constants.GameWorld)
    if world:HasEntity(Constants.CatHouseEntityId) then
        world:DestroyEntityImmediately(Constants.CatHouseEntityId)
    end
    self.sceneCos = nil
    self:DeleteCats()
    if not isNull(self.pngWriter) then
        self.pngWriter.onComplete = nil
        self.pngWriter = nil
    end
    self.captureCamera = nil
    if not isNull(self.captureGo) then
        KTool.SafeDelete(self.captureGo, true)
    end
    self:DeleteMarketingStorage()
    -- if not isNull(self.loader) then
    --     self.loader:Release()
    --     self.loader = nil
    -- end
    self.catBornGo = nil
    self.catBlindBoxGo = nil
    CatHouseMgr.cats = nil
    self.captureGo = nil

    self:StopDataDetailsCo()

  
end
