---Initialize
---@param isSingleExplore boolean
---初始化的逻辑
function CatHouseMgr:Initialize(isSingleExplore)
    isSingleExplore = checkBool(isSingleExplore)
    if isSingleExplore then
        CatHouseExploreMgr = import("Game.CatHouse.Explore.CatHouseExploreMgr")
        CatHouseExploreMgr:Init()
        xTry(function() 
            cs_coroutine.yield_return(self:MakeSureCaptureGo())
            ---是否请求 测试下
            self:RequestCatHouseHome()
        end)
    else
        if isNull(self.catBornGo) then
            self.catBornGo = GameObject.Find(CatBornNodeName)
        end
        self.handler = Events.AddListener(Constants.EventNames.CatHouseDynamicCatChangeEventName, Bind(self, self.StartLoadCat))
        self.handlerSwitch = Events.AddListener(Constants.EventNames.CatHouseSwitchUserEvent, Bind(self, self.SwitchUser))
        self.handlerGet = Events.AddListener(CAT_GET_POPUP_FINISH, Bind(self, self.ExecuteOpenCardSkill))
        CatHouseExploreMgr = import("Game.CatHouse.Explore.CatHouseExploreMgr")
        CatHouseExploreMgr:Init()
        if isNull(self.captureGo) then
            local modelLoader = ResourceModule.LoadBundleAsync(CapturePrefabPath, nil, true)
            while not modelLoader.IsCompleted do
                cs_coroutine.yield_return(Yielders.EndOfFrame)
            end
            if not isNull(modelLoader.ResultObject) then
                ---@type UnityEngine.GameObject
                -- local modelIns = GameObject.Instantiate(modelLoader.ResultObject)
                local modelIns = modelLoader:Instantiate()
                modelLoader:Release()

                modelIns.name = "CAPTURE_SCREEN"
                self.captureGo = modelIns
                -- self.loader = modelLoader
                self.pngWriter = modelIns:GetComponentInChildren(typeof(AutoPNGWriter), true)
                if not isNull(self.pngWriter) then
                    self.pngWriter.onComplete = function(id, path)
                        --print(id, path)
                        Events.Broadcast(CatHouseCaptureTextureComplete, id, path)
                    end
                end
                self.captureCamera = modelIns.transform:Find(CaptureCameraName).gameObject
            else
                modelLoader:Release()
                return
            end
            ---是否请求 测试下
            self:RequestCatHouseHome()
            self:DeleteCats()
            ---删除旧的猫
            self:StartLoadCat()
            ---加载养成场景
            ---@type SceneManagement
            local sceneManagement = SceneManagement:GetInstance()
            self:LoadScenes(sceneManagement)
            local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
            CriWareUtils.PlayMusicById("bgm_cathouse")
            --cs_coroutine.yield_return(self:JudgeFirstEnterCatHouse())
        end
    end
end
