    self:StartLoadCat()
end

---JudgeFirstEnterCatHouse
---判断是否是第一次进入猫屋
function CatHouseMgr:JudgeFirstEnterCatHouse()
    --- 关闭引导 走老逻辑
    local AppEngine = CS.Engine.Lib.AppEngine
    local IsOpenGuide = AppEngine.GetConfig("Engine.Dev", "IsOpenGuide")
    if tonumber(IsOpenGuide) == 0 then
        ---@type CatHouseComponent
        local component = GameUtils.CreateEntityWithComponent(Constants.CatHouseEntityId, ECSComponentType.Constants.CatHouseComponent)
        local key = string.format('%s_', "Enter_Cat_House")
        local recordData = CfUtils.GetLocalData(key, '')
        if string.isEmpty(recordData) then
            ---判断是否是第一次进入猫屋
            CfUtils.WriteLocalData(key, key)
            ---猫列表为1个，初始送的猫，并且解锁的基因为0
            if component and table.count(checkTable(component._catHouseHomeDojo.catList)) == 1 then
                local cat = table.takeFirst(component._catHouseHomeDojo.catList)
                return UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseCultivationGetCatPopup, parameters = { viewType = 1, playerCatId = cat.id, isUnlockCardSill = true } })

            end
        end
        return
    end

    --- 猫屋打脸跟着引导走 引导不完 重进一次打一次
    ---@type GuideComponent
    local guideComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)
    if not guideComponent:CheckOneCondition(Constants.GuideConditionType.CompleteSpecifyModule, Constants.GuideModule.CatCultivation) then
        ---@type CatHouseComponent
        local component = GameUtils.CreateEntityWithComponent(Constants.CatHouseEntityId, ECSComponentType.Constants.CatHouseComponent)
        if component == nil or #component:GetCatHouseHomeDojo().catList < 1 then
            return
        end
        local cat = table.takeFirst(component._catHouseHomeDojo.catList)
        return UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseCultivationGetCatPopup, parameters = { viewType = 1, playerCatId = cat.id, isUnlockCardSill = true } })
    end

end

