function CatHouseMgr:StartLoadCat()
    local component = nil
    if self:IsMyself() then
        component = GameUtils.CreateEntityWithComponent(Constants.CatHouseEntityId, ECSComponentType.Constants.CatHouseComponent)
    else
        component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CatHouseOtherPlayerComponent, Constants.CatHouseEntityId)
    end
    if component then
        local t, seqKeys = component:GetShowCats()
        if #t > 0 then
            local seqId = KTool.XxHash32(table.concat(seqKeys, '-'))
            if self.preShowCatsId ~= seqId then
                self:DeleteCats()
                if not isNull(self.cat_coroutine) then
                    cs_coroutine.stop(self.cat_coroutine)
                    self.cat_coroutine = nil
                end
                self.preShowCatsId = seqId
                ---@type SceneManagement
                local sceneManagement = SceneManagement:GetInstance()
                ---请求完成后构建猫
                self.cat_coroutine = cs_coroutine.start(function()
                    local len = #t
                    local isFinish = false
                    for i, v in pairs(t) do
                        local genes = {}
                        for _, v in pairs(v.genes) do
                            table.insert(genes, checkNumber(v.geneId))
                        end
                        cs_coroutine.yield_return(CatHouseMgr:GetInstance():LoadCatModelAsync(checkNumber(v.age), checkNumber(v.catId), false, genes, self.catBornGo, function(go)
                            ---@type UnityEngine.Transform
                            local trans = go.transform
                            go.name = tostring(v.id)
                            --sceneManagement:GetSceneInstance(Constants.IdSceneSetting21):AddCacheObject(go)
                            trans.position = Vector3.New(-0.5, 0, 0.6)
                            trans.localPosition = Vector3.New(-0.5, 0, 0.6)
                            trans.localRotation = Quaternion.Euler(0, 12, 0)
                            ---@type CatAI
                            local goEnv = AddLuaBehaviour(go, CatAIPath)
                            if isNull(goEnv.Env) then
                                goEnv:Init()
                            end
                            table.insert(CatHouseMgr.cats, goEnv)
                            goEnv.Env:SetCatPlayerId(v.id, checkNumber(v.age))
                            --local tap = go.gameObject:EnsureComponent(typeof(QuickTap))--猫屋主界面猫咪点击进入交互主界面
                            --tap.onTap:RemoveAllListeners()
                            --if i == len then
                            --    isFinish = true
                            --end
                            --tap.onTap:AddListener(function(gesture)
                            --    if isFinish then
                            --        UIModule.OpenDialog({id = Constants.UITypeIds.CatHouseInteractionDialog, parameters = {catId = v.id}},
                            --                {
                            --                    --{id = Constants.UITypeIds.CatHouseCatListDialog}
                            --                }
                            --        )
                            --    end
                            --end)

                        end))
                    end
                    while not isFinish do
                        cs_coroutine.yield_return()
                    end
                end)
            end
        else
            ---要删除所有猫
            self:DeleteCats()
        end
    end
end

