---CaptureTexture
---捕获纹理
---@param bornType  number 成长类型  1 幼年，2 成年
---@param catTypeId number 猫类型   101 狸花 102 美短 103 布偶 104 三花
---@param attributes table 猫基因
---@param isMarket boolean 是否市集
function CatHouseMgr:CaptureTexture(bornType, catTypeId, attributes, isMarket, fileNameId)
    if isNull(self.pngWriter) then return end
    isMarket = checkBool(isMarket)
    -- table.sort(attributes, function(a, b)
    --     return checkNumber(a) < checkNumber(b)
    -- end)
    -- local fileNameId = self:GetFileNameId(bornType, catTypeId, attributes)

    local recordingPath = AutoPNGWriter.GetStorageFilePath(tostring(catTypeId), fileNameId, isMarket)
    local isExists = File.Exists(recordingPath)
    if not isExists then
        self.pngWriter:Create(fileNameId, checkNumber(bornType), tostring(catTypeId), attributes, self.captureCamera.gameObject, self.captureCamera, Vector3.New(-0.02, -0.12, 5), Vector3.New(0, -140, 0), "Arts/Prefab_cat/Prefab_catparts", isMarket)
    else
        Events.Broadcast(CatHouseCaptureTextureComplete, fileNameId, recordingPath)
    end

    -- return fileNameId, isExists, recordingPath
end

---GetFileNameId
---@param bornType  number 成长类型  1 幼年，2 成年
---@param catTypeId number 猫类型 101 狸花 102 美短 103 布偶 104 三花
---@param attributes table 猫属性
function CatHouseMgr:GetFileNameId(bornType, catTypeId, attributes)
    table.sort(attributes, function(a, b)
        return checkNumber(a) < checkNumber(b)
    end)
    local seq = string.format("%s-%s-%s", tostring(bornType), tostring(catTypeId), table.concat(attributes, "-"))
    ---下面的逻辑只能改变因修改色彩的逻辑处理不用重新截图，不能影响因3d贴图修改的处理
    local setting = settingMgr:GetSetting(AutoIds.IdSetting1902, CatHouseCatDataVo)
    local t = {}
    for _, attributeId in pairs(attributes) do
        ---@type CatHouseCatDataVo
        local vo = setting:Get(attributeId)
        if vo then
            table.insert(t, tostring(vo.unitAddress))
            table.insert(t, tostring(vo.unitPoint))
            table.insert(t, tostring(vo.textureAddress))
            table.insert(t, tostring(vo.textureId))
            table.insert(t, tostring(vo.colourList))
        end
    end
    if #t > 0 then
        local extra = table.concat(t, '')
        seq = seq .. extra
    end
    local fileNameId = KTool.XxHash32(seq)
    return fileNameId
end

function CatHouseMgr:CheckStorageFileIsExist(bornType, catTypeId, attributes, isMarket)
    isMarket = checkBool(isMarket)
    table.sort(attributes, function(a, b)
        return checkNumber(a) < checkNumber(b)
    end)
    local fileNameId = self:GetFileNameId(bornType, catTypeId, attributes)
    local recordingPath = AutoPNGWriter.GetStorageFilePath(catTypeId, fileNameId, isMarket)
    return File.Exists(recordingPath), recordingPath
end

---LoadCaptureTexture
---@param path string 资源路径
function CatHouseMgr:LoadCaptureTexture(path, isMarket)
    local t = isMarket and self.marketPath2Texture or self.path2Texture
    local texture = t[path]
    if isNull(texture) then
        texture = TextureUtility.LoadTexture(path)
        t[path] = texture
    end
    return texture
end
--- 清理 路径2纹理
---@param isMarket any
function CatHouseMgr:ClearPath2Texture(isMarket, isDestroy)
    local Object = CS.UnityEngine.Object
    local t = isMarket and self.marketPath2Texture or self.path2Texture
    for k, v in pairs(t) do
        Object.Destroy(v)
    end
    if isMarket then
        self.marketPath2Texture = not isDestroy and {} or nil
    else
        self.path2Texture = not isDestroy and {} or nil
    end
end

---CalcCatPrice
---计算猫价格
---@param catData table
function CatHouseMgr:CalcCatPrice(catData)
    local genes = catData.genes
    local priceData = {}
    local priceMap = {}
    for i, v in ipairs(genes) do
        ---@type CatHouseCatDataVo
        local catHouseCatDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, CatHouseCatDataVo, v.geneId)
        if priceMap[checkString(catHouseCatDataVo.coinId)] then
            priceMap[checkString(catHouseCatDataVo.coinId)] = priceMap[checkString(catHouseCatDataVo.coinId)] + catHouseCatDataVo.coinNum
        else
            priceMap[checkString(catHouseCatDataVo.coinId)] = catHouseCatDataVo.coinNum
        end
    end
    for i, b in pairs(priceMap) do
        table.insert(priceData, {
            id = i,
            num = b,
        })
    end
    return priceData
end

---@param actionType ConstantsCatAction
function CatHouseMgr:PlayRandomCatAction(catGameObject, actionType, endCallBack)
    local length1 = table.count(actionType)
    local randomIndex1 = math.random(1, length1)--动作中随机
    local data = actionType[randomIndex1]
    local length2 = table.count(data.faceId)
    local isChangeFace = false
    local randomIndex2
    local faceId
    if length2 > 0 then
        isChangeFace = true
        randomIndex2 = math.random(1, length2)--表情中随机
        faceId = data.faceId[randomIndex2]
    end
    local animancerComp = KTool.GetComponent(catGameObject, typeof(NamedAnimancerComponent))
    local QCatComp = KTool.GetComponent(catGameObject, typeof(CS.Game.Native.Corder.QCat))
    local animancerState = animancerComp:TryPlay(data.actionId)
    if isChangeFace then
        QCatComp:SetEmotionId(faceId, animancerState.Length)
    end
    if not isNull(animancerState) then
        animancerState.Events:SetEndAction(function()
            animancerState.Events:SetEndAction(nil)
            if endCallBack then
                endCallBack()
            end
        end)
    end
end


