function CatHouseMgr:RequestCatHouseHome()
    cs_coroutine.yield_return(GameUtils.Request(Interfaces.CatHouseHome, {}, function(req, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local data = checkTable(response.data)
        ---@type CatHouseComponent
        local component = GameUtils.CreateEntityWithComponent(Constants.CatHouseEntityId, ECSComponentType.Constants.CatHouseComponent)
        component:InitialDojo(data)
    end))
end


