---设置伙伴猫
---@param playerCatId number @ 猫唯一id
---@param successCB fun():void @ 设置成功的回调
function CatHouseMgr:SetPartyCat(playerCatId, successCB)
    GameUtils.Request(
            Interfaces.CatHouseSetPartyCat,
            { playerCatId = playerCatId },
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    ---@type CatHouseComponent
                    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
                    local catHouseHomeDojo = component:GetCatHouseHomeDojo()
                    ---维护数据，刷新下层界面的信息
                    catHouseHomeDojo:FillFieldData("partyCatId", playerCatId)
                    ---维护数据 更新playerDojo 伙伴猫信息
                    local catData = component:GetCatDataById(playerCatId)
                    local curCatGenes = {}
                    for i, v in ipairs(catData.genes) do
                        table.insert(curCatGenes, checkNumber(v.geneId))
                    end
                    ---@type PlayerComponent
                    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                    local partyCatInfo = playerComponent:GetPlayerDojo().partyCatInfo
                    partyCatInfo.playerCatId = playerCatId
                    partyCatInfo.catId = catData.catId
                    partyCatInfo.genes = curCatGenes

                    GameUtils.Toast(localize("已将猫咪设置为伙伴猫"))
                    if successCB then
                        successCB()
                    end
                end
            end
    )
end

function CatHouseMgr:GetAttributes(genes)
    local attributes = {}
    for i, v in ipairs(genes) do
        table.insert(attributes, v.geneId)
    end
    return attributes
end

---CheckCatActionLimit
---检查猫动作现在
---@param actionType number 动作类型    猫咪状态表的key
---@param catId number      猫的唯一id
---@return number ConstantsCatHouse.CatStatus 处于猫状态 nil 无状态
function CatHouseMgr:CheckCatActionLimit(actionType, catId)
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local cdData = component:GetCDDataById(catId)
    local catState
    if cdData then
        ---@type CatHouseCatStatusVo
        local catStatusVo = CfUtils.GetCfVo(AutoIds.IdSetting1907, "CatHouseCatStatusVo", actionType)
        local astrictId = catStatusVo.astrictId
        for i, state in ipairs(astrictId) do
            if cdData[checkNumber(state)] ~= nil then
                catState = checkNumber(state)
                break
            end
        end
    end
    return catState
end

---FilterCatListByActionLimit
---根据行为限制过滤猫列表
---@param actionType number
function CatHouseMgr:FilterCatListByActionLimit(actionType, viewType, extraParams)
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local catList = component:GetCatHouseHomeDojo().catList
    ---@type CatHouseCatStatusVo
    local catStatusVo = CfUtils.GetCfVo(AutoIds.IdSetting1907, "CatHouseCatStatusVo", actionType)
    local catStateList = catStatusVo.astrictId
    local geneId = extraParams and checkNumber(extraParams.geneId) or 0
    local CatActionType = ConstantsCatHouse.CatActionType
    --- 1. 初始化检查方法
    local CheckCallback
    if actionType == CatActionType.HatchingInvitation or actionType == CatActionType.RallySignup then
        CheckCallback = function(v)
            return checkNumber(v.deliveryRemainTimes) > 0 and checkNumber(v.age) == BornType.Adult
        end
    else
        CheckCallback = function(v)
            return checkNumber(v.age) == BornType.Adult
        end
    end

    --- 2. 过滤数据
    local t = {}
    for i, v in ipairs(catList) do
        local genes = v.genes
        --- 2.1 过滤基因
        if self:FilterGeneId(genes, geneId) then
            --- 2.2 检查动作限制附加条件
            local result = CheckCallback(v)
            if result then
                --- 2.3 检查猫状态
                local cdData = component:GetCDDataById(v.id)
                if cdData then
                    for _, state in ipairs(catStateList) do
                        if cdData[checkNumber(state)] ~= nil then
                            result = false
                            break
                        end
                    end
                end
            end
            if result then
                table.insert(t, v)
            end
        end
    end
    return t
end

---SortCat
---@param catList table     猫列表
---@param sortType number   Constants.SortType
---@param asc boolean       升序
---@param partyCatId number 伙伴猫Id
function CatHouseMgr:SortCat(catList, sortType, asc, partyCatId)

    ---伙伴猫>场景中显示猫>按出生日期降序排序猫>未孵化出的猫
    catList = checkTable(catList)
    sortType = checkNumber(sortType)
    asc = checkBool(asc)
    partyCatId = checkNumber(partyCatId)

    local t
    if sortType == Constants.SortType.Price then
        t = clone(catList)
    else
        t = {}
        table.walk(clone(catList), function(_, v)
            v.partyCatFlag = checkNumber(v.id) == partyCatId and 1 or 0
            v.hatchFlag = checkTable(v.status)[CatStatus.Hatching] ~= nil and 0 or 1
            table.insert(t, v)
        end)
    end

    local fieldNames
    local customAscConfig = {
        ["partyCatFlag"] = true,
        ["isShow"] = true,
        ["hatchFlag"] = true,
        ["remainTime"] = false,
    }
    if sortType == Constants.SortType.Birthday then
        fieldNames = { "partyCatFlag", "hatchFlag", "isShow", "id" }
    elseif sortType == Constants.SortType.DeliveryTimes then
        fieldNames = { "partyCatFlag", "hatchFlag", "isShow", "deliveryRemainTimes" }
    elseif sortType == Constants.SortType.Hp then
        fieldNames = { "partyCatFlag", "hatchFlag", "isShow", "hp" }
    elseif sortType == Constants.SortType.Price then
        customAscConfig = nil
        fieldNames = { "price", "remainTime" }
    end

    if fieldNames then
        ---装备稀有度排序
        table.sort(t, function(a, b)
            return CommonChecker(a, b, fieldNames, asc, customAscConfig)
        end)
    end

    return t
end

---ScreenCat
---@param data table  猫列表
---@param screenDic table<number, table<number, number>> {screenType = {condition}}
---@param screenDataSpecifyGenaIdDic table table<number, table<number, number>> {place = {[geneId] = geneId}}
function CatHouseMgr:ScreenCat(data, screenDic, screenDataSpecifyGenaIdDic)
    local cloneData = clone(data)
    if screenDic == nil or next(screenDic) == nil then
        return cloneData
    end

    local screenType2ConditionDict = {}
    for type, screenClassDic in pairs(screenDic) do
        local conditionDict = {}
        for i, v in pairs(screenClassDic) do
            conditionDict[v] = v
        end
        screenType2ConditionDict[checkNumber(type)] = conditionDict
    end

    local ScreenTypeCheck = {
        [Constants.ScreenType.CatType] = function(v, conditionDict)
            return conditionDict[checkNumber(v.catId)] ~= nil
        end,
        [Constants.ScreenType.CatDataType] = function(v, conditionDict)
            local genes = checkTable(v.genes)
            for _, gene in ipairs(genes) do
                ---@type CatHouseCatDataVo
                local catHouseCatDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, CatHouseCatDataVo, gene.geneId)
                if conditionDict[checkNumber(catHouseCatDataVo.kind)] then
                    return true
                end
            end
            return false
        end,
        [Constants.ScreenType.CatDataSpecifyType] = function(v, conditionDict)
            local genes = checkTable(v.genes)
            for _, gene in ipairs(genes) do
                local geneId = gene.geneId
                ---@type CatHouseCatDataVo
                local catHouseCatDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, CatHouseCatDataVo, geneId)
                local place = catHouseCatDataVo.place
                --- 包含对应小类 并且 (指定基因类型是空的 或 对应小类包含该基因Id)
                if next(screenDataSpecifyGenaIdDic) == nil or (conditionDict[checkNumber(place)] and (checkTable(screenDataSpecifyGenaIdDic[tostring(place)])[tostring(geneId)] ~= nil)) then
                    return true
                end
            end
            return false
        end,
    }

    local t = {}
    for i, v in ipairs(cloneData) do
        local checkRes   = true
        for screenType, conditionDict in pairs(screenType2ConditionDict) do
            checkRes = checkRes and ScreenTypeCheck[screenType](v, conditionDict)
        end
        if checkRes then
            table.insert(t, v)
        end
    end

    return t
end

