---@param viewType number ConstantsCatHouse.CatListType
---@return boolean 是否显示成功
function CatHouseMgr:ShowCatListDialogByActionLimit(actionLimit, viewType, excludeIdList, extraParams)
    --- 1. 获取能使用的猫列表
    ---@type CatHouseComponent
    local t = self:FilterCatListByActionLimit(actionLimit, viewType, extraParams)

