        local actionLimit2ToastText = {
            [ConstantsCatHouse.CatActionType.HatchingInvitation] = localize("当前没有可以参与孵化的猫咪"),
            [ConstantsCatHouse.CatActionType.RallySignup] = localize("当前没有可以参与集会登记的猫咪"),
        }

        GameUtils.Toast(actionLimit2ToastText[actionLimit])
        return false
    end

    --- 3. 进入猫列表
    local viewType2DialogId = {
        [ConstantsCatHouse.CatListType.Cultivation] = Constants.UITypeIds.CatHouseMyCatDialog,
        ---TODO
        [ConstantsCatHouse.CatListType.Signup] = Constants.UITypeIds.CatHouseMyCatDialog,
    }
