---RequestRallyList
function CatHouseMgr:RequestRallyCats(requestParams, cb, extraParams)
    GameUtils.Request(Interfaces.CatHouseRallyCats, requestParams or {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local catList = response.data.catList
        --- 2. 生成集会列表界面所需数据
        local geneId = extraParams and checkNumber(extraParams.geneId) or 0
        local t = self:GenerateRallyList(catList, geneId)

        if cb then
            cb(t)
        end
        
    end)
end

function CatHouseMgr:GenerateRallyList(catList, geneId)
    local t = {}
    for i, v in ipairs(catList) do
        local catData = v.playerCatHousePet
        local genes = catData.genes
        if self:FilterGeneId(genes, geneId) then
            catData.age = BornType.Adult
            catData.price = checkNumber(v.price)
            catData.playerId = checkNumber(v.playerId)
            catData.rallyCats = checkNumber(v.playerId)
            catData.remainTime = checkNumber(v.remainTime)
            table.insert(t, catData)
        end

    end

    return t

end

---FilterGeneId
---过滤基因id
---@param genes table 基因列表
---@param geneId number 基因id
function CatHouseMgr:FilterGeneId(genes, geneId)
    if geneId == 0 then
        return true
    end
    for i, geneData in ipairs(genes) do
        if checkNumber(geneData.geneId) == geneId then
            return true
        end
    end
    return false
end

---CheckDeliverySeat
---检查有没有可用的培育池
---@return number 培育池id
function CatHouseMgr:CheckDeliverySeat()
    local CatCultivationType = ConstantsCatHouse.CatCultivationType
    ---@type CatHouseComponent
    local component = GameUtils.CreateEntityWithComponent(Constants.CatHouseEntityId, ECSComponentType.Constants.CatHouseComponent)
    local deliveryList = component:GetCatHouseHomeDojo().deliveryList
    local catData = KCookie.Get(ConstantsCatHouse.CookieMyCatDataName)
    local deliveryId
    local catStatus = (catData ~= nil and catData.status[CatStatus.Waiting] ~= nil) and CatStatus.Waiting or 0
    local catIsWaiting = catStatus == CatStatus.Waiting
    for i, v in ipairs(deliveryList) do
        --- 如果猫处于等待好友请求中则需要返回 猫所在的培育池
        if catIsWaiting then
            if checkNumber(v.status) == CatCultivationType.FriendsConfirming and checkNumber(v.playerCatId) == checkNumber(catData.id) then
                deliveryId = checkNumber(v.deliveryId)
                break
            end
        else
            if checkNumber(v.status) == CatCultivationType.Add then
                deliveryId = checkNumber(v.deliveryId)
                break
            end

        end
    end

    if deliveryId == nil then
        GameUtils.Toast(localize("暂无可用的孵化位置"))
        return
    end
    return deliveryId
end

---BackToMatchPopup
---返回到配对界面
---@param isCheckSeat boolean 是否检查培育位置
---@param isCloseToHome boolean 是否关闭界面到猫屋主界面
function CatHouseMgr:BackToMatchPopup(isCheckSeat, isCloseToHome, isFromInteraction, excludeId, needRemoveRecordId)
    if isCheckSeat then
        --- 检查有没有可用的培育池
        local deliveryId = self:CheckDeliverySeat()
        if deliveryId == nil then
            return nil, false
        end
        UIRaycastBlocker:AddCondition("CatHouseMgr.BackToMatchPopup")
        return cs_coroutine.start(function()
            if isCloseToHome then

                if needRemoveRecordId then
                    UIModule.RemoveRecordToCustomDialog(needRemoveRecordId)
                end
                local co = GameUtils.CloseDialog2AppointDialog(Constants.UITypeIds.CatHouseMatchPopup, Constants.UITypeIds.CatHouseMainDialog)
                if co then
                    cs_coroutine.yield_return(co)
                end
            end
            --- 从培育界面启配对界面
            UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseCultivationPopup, parameters = { deliveryId = deliveryId, isFromInteraction = isFromInteraction } }, excludeId)
            UIRaycastBlocker:RemoveCondition("CatHouseMgr.BackToMatchPopup")
        end), true
    else
        return UIModule.BackDialog(), true
    end
end

