        local heritableVo = setting:Get(geneId)
        if heritableVo then
            for i, v in pairs(heritableVo.catId) do
                local vo = self:GetCatVoByRefId(v)
                table.insert(t, vo.name)
            end
        end
    else
        ---@type BaseSetting
        local setting = CfUtils.GetCf(AutoIds.IdSetting1906, "CatHouseCatVo")
        local vv = setting:GetAll()
        for i, v in pairs(vv) do
            table.insert(t, v.name)
        end
    end
    return t
end

