---GetCatListUpLimit
--- 获取猫列表上限
function CatHouseMgr:GetCatListUpLimit()
    ---猫咪列表初始空位
    local catListInitCount = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.CatListInitCount).num)
    local setting = CfUtils.GetCfTable(AutoIds.IdSetting1914)
    local allRow = setting:GetAll()
    for i, row in pairs(allRow) do
        catListInitCount = catListInitCount + checkNumber(row:Get("placeNum"))
    end
    return catListInitCount
end

---GetCatListExpansionTimes
--- 获取猫列表扩容次数
function CatHouseMgr:GetCatListExpansionTimes(maxCatsNum)
    ---猫咪列表初始空位
    local catListInitCount = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.CatListInitCount).num)
    maxCatsNum = maxCatsNum - catListInitCount
    if maxCatsNum <= 0 then
        return 0
    end

    local setting = CfUtils.GetCfTable(AutoIds.IdSetting1914)
    local allRow = setting:GetAll()
    local catListInitCount = 1
    for i, row in pairs(allRow) do
        maxCatsNum = maxCatsNum - checkNumber(row:Get("placeNum"))
        if maxCatsNum <= 0 then
            break
        end
        catListInitCount = catListInitCount + 1
    end

    return catListInitCount

end

