function CatHouseMgr:GetGeneRateUpActivityData()
    return self.geneRateUpActivityData
end
function CatHouseMgr:SetGeneRateUpActivityData(data) 
    self.geneRateUpActivityData = data
end

function CatHouseMgr:CheckGeneRateUpIsOpen(cb)
    local _dataActivity = self:GetGeneRateUpActivityData()
    if _dataActivity then
        if cb then
            cb(_dataActivity)
        end
        return
    end
    
    local _idActivityGeneRateUpType = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.ActivityGeneRateUpTypeId).num)
    GameUtils.Request(Interfaces.ActivityHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        _dataActivity = {}
        local data = checkTable(response.data)
        for i, activity in ipairs(checkTable(data.activities)) do
            local type = checkNumber(activity.type)
            if _idActivityGeneRateUpType == type then
                _dataActivity.id = checkNumber(activity.id)
                _dataActivity.type = checkNumber(activity.type)
                _dataActivity.startTime = checkNumber(activity.startTime)
                _dataActivity.endTime = checkNumber(activity.endTime)
                _dataActivity.closeTime = checkNumber(activity.closeTime)
                _dataActivity.name = checkString(activity.name)
                _dataActivity.detail = checkString(activity.detail)
                self:SetGeneRateUpActivityData(data)
                if cb then
                    cb(_dataActivity)
                end
                break
            end
        end
    end)
end

function CatHouseMgr:GeneRateUpReq(activityData, cb)
    if self.timerGeneRateUp then
        if cb then
            cb(self:HandleGeneRateUpResponse(self:GetGeneRateUpData()), activityData)
        end
        return
    end
    local activityId = checkNumber(activityData.id)
    GameUtils.Request(Interfaces.CatHouseGeneRateUp, { activityUuid = activityId }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local data = checkTable(response.data)
        self:SetGeneRateUpData(data)
        self:SetTimerGeneRateUp(activityData)
        if cb then
            cb(self:HandleGeneRateUpResponse(data), activityData)
        end
    end)
end

function CatHouseMgr:GetGeneRateUpData()
    return self.geneRateUpData
end
function CatHouseMgr:SetGeneRateUpData(data)
    self.geneRateUpData = data
end

function CatHouseMgr:HandleGeneRateUpResponse(data)
    return {
        theme = checkNumber(data.theme),
        picture = checkString(data.picture),
        basicGenes = checkTable(data.basicGenes),
        componentGenes = checkTable(data.componentGenes)
    }
end

function CatHouseMgr:SetTimerGeneRateUp(activityData)
    self:CleanTimerGeneRateUp()
    local endTime = activityData.endTime
    local timeCount = checkNumber(endTime)
    if timeCount <= 0 then
        return
    end
    local CatHouseGeneRateUpCDChange = Constants.EventNames.CatHouseGeneRateUpCDChange
    self.timerGeneRateUp = CDTimerModule.GetInstance():AddCD(1, function(count, id, countElapsed)
        if count <= 0 then
            self:CleanTimerGeneRateUp()
        end

        local activityData = self:GetGeneRateUpActivityData()
        if activityData then
            activityData.endTime   = count
        end
        Events.Broadcast(CatHouseGeneRateUpCDChange, count)

    end, math.abs(timeCount), false, true, true)
    self.timerGeneRateUp.OnRemove = nil
end

function CatHouseMgr:CleanActionTimerGeneRateUp()
    if not isNull(self.timerGeneRateUp) then
        self.timerGeneRateUp.OnCd = nil
        self.timerGeneRateUp.OnRemove = nil
    end
end

function CatHouseMgr:CleanTimerGeneRateUp()
    if not isNull(self.timerGeneRateUp) then
        self:CleanActionTimerGeneRateUp()
        CDTimerModule.GetInstance():RemoveCD(self.timerGeneRateUp)
        self.timerGeneRateUp = nil
        --- clear Gene Rate Up Data
        self:SetGeneRateUpData()
        self:SetGeneRateUpActivityData()
    end
end

---只是弄个函数，不想要可以删掉
function CatHouseMgr:MakeSureCaptureGo()
    if isNull(self.captureGo) then
        local modelLoader = ResourceModule.LoadBundleAsync(CapturePrefabPath, nil, true)
        while not modelLoader.IsCompleted do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
        if not isNull(modelLoader.ResultObject) then
            ---@type UnityEngine.GameObject
            -- local modelIns = GameObject.Instantiate(modelLoader.ResultObject)
            local modelIns = modelLoader:Instantiate()
            modelLoader:Release()
            modelIns.name = "CAPTURE_SCREEN"
            self.captureGo = modelIns
            -- self.loader = modelLoader
            self.pngWriter = modelIns:GetComponentInChildren(typeof(AutoPNGWriter), true)
            if not isNull(self.pngWriter) then
                self.pngWriter.onComplete = function(id, path)
                    --print(id, path)
                    Events.Broadcast(CatHouseCaptureTextureComplete, id, path)
                end
            end
            self.captureCamera = modelIns.transform:Find(CaptureCameraName).gameObject
        else
            modelLoader:Release() return
        end
    end
end

return CatHouseMgr